#include <iostream>
#include <string>
#include <iomanip>
#include <sstream>

class Clock {
public:
    // Mutator: takes formatted string HH:MM:SS, validates, stores internal seconds
    void setTime(const std::string& timeStr) {
        std::istringstream stream(timeStr);
        int h = 0, m = 0, s = 0;
        char sep1 = '\0', sep2 = '\0';
        if ((stream >> h >> sep1 >> m >> sep2 >> s) && sep1 == ':' && sep2 == ':') {
            if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
                totalSeconds = h * 3600 + m * 60 + s;
                return;
            }
        }
        totalSeconds = 0; // Fallback on invalid format
    }

    // Accessor: converts internal seconds to formatted HH:MM:SS
    std::string getTime() const {
        int h = totalSeconds / 3600;
        int m = (totalSeconds % 3600) / 60;
        int s = totalSeconds % 60;
        std::ostringstream out;
        out << std::setfill('0') << std::setw(2) << h << ":"
            << std::setfill('0') << std::setw(2) << m << ":"
            << std::setfill('0') << std::setw(2) << s;
        return out.str();
    }

    // Internal member function relies on getTime() rather than raw totalSeconds
    void display() const {
        std::cout << "Current time: " << getTime() << std::endl;
    }

private:
    int totalSeconds{0};
};

int main() {
    Clock clk;
    clk.setTime("14:30:15");
    clk.display();
    return 0;
}

#include <iostream>
#include <string>
#include <utility>

class GradeBook {
public:
    // Single-argument constructor declared explicit to prevent implicit conversions
    explicit GradeBook(std::string name)
        : courseName(std::move(name)) // member initializer list
    {
        // Empty body
    }

    void setCourseName(std::string name) {
        courseName = std::move(name);
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        // Calls getCourseName() rather than accessing courseName directly
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!" << std::endl;
    }

private:
    std::string courseName;
};

int main() {
    GradeBook gradeBook1("CS101 Introduction to C++ Programming");
    GradeBook gradeBook2("CS102 Data Structures in C++");

    std::cout << "gradeBook1 created for course: " << gradeBook1.getCourseName() << std::endl;
    std::cout << "gradeBook2 created for course: " << gradeBook2.getCourseName() << std::endl;

    gradeBook1.displayMessage();
    return 0;
}
